// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure operation is pending before cancelling
        vm.assume(id != bytes32(0));
        // Ensure operation is not already done
        vm.assume(c.getTimestamp(id) != 1);

        // Cancel an operation
        c.cancel(id);

        // After cancelling, check supportsInterface returns true for both interfaces
        bool supportsIAC = c.supportsInterface(type(IAccessControl).interfaceId);
        bool supportsIERC165 = c.supportsInterface(type(IERC165).interfaceId);
        assertTrue(supportsIAC && supportsIERC165, "supportsInterface should return true for both IAccessControl and IERC165");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // Ensure we can call cancel without reverting due to missing role or operation state
        vm.assume(role != bytes32(0)); // avoid default admin role issues
        // Grant PROPOSER_ROLE to this contract so we can schedule and cancel
        c.grantRole(keccak256("PROPOSER_ROLE"), address(this));
        // Schedule a dummy operation to make cancel possible
        c.schedule(address(this), 0, "", bytes32(0), bytes32(0), 1);
        // Record supportsInterface result before cancel
        bool before = c.supportsInterface(type(IERC165).interfaceId);
        // Perform cancel
        c.cancel(keccak256(abi.encode(address(this), 0, "", bytes32(0), bytes32(0))));
        // Record supportsInterface result after cancel
        bool after = c.supportsInterface(type(IERC165).interfaceId);
        // The result must remain unchanged
        assertTrue(before == after);
    }
}

