pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, address proposer, address executor) public {
        vm.assume(proposer != address(0) && proposer != address(this) && proposer != address(c));
        vm.assume(executor != address(0) && executor != address(this) && executor != address(c));
        // Grant PROPOSER_ROLE to proposer
        c.grantRole(c.PROPOSER_ROLE(), proposer);
        // Grant EXECUTOR_ROLE to executor
        c.grantRole(c.EXECUTOR_ROLE(), executor);
        // Try to cancel a non-pending operation as proposer
        vm.prank(proposer);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));
        // The cancel should revert because the operation is not pending (isOperationPending returns false)
        assertTrue(!success);
    }
}

