pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(bytes32 role) public {
        // The reference contract's getRoleAdmin returns the correct admin role.
        // For TIMELOCK_ADMIN_ROLE (keccak256("TIMELOCK_ADMIN_ROLE")) the admin is itself.
        // For PROPOSER_ROLE and EXECUTOR_ROLE, admin is TIMELOCK_ADMIN_ROLE.
        // The buggy version always returns 0x00.
        // We assert that for any role, getRoleAdmin returns the expected admin role.
        // Compute the expected admin role for the given role:
        bytes32 timelockAdminRole = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        bytes32 executorRole = keccak256("EXECUTOR_ROLE");

        bytes32 expectedAdmin;
        if (role == timelockAdminRole) {
            expectedAdmin = timelockAdminRole;
        } else if (role == proposerRole || role == executorRole) {
            expectedAdmin = timelockAdminRole;
        } else {
            // For any other role, the admin role defaults to 0x00 (DEFAULT_ADMIN_ROLE)
            expectedAdmin = bytes32(0x00);
        }

        assertTrue(c.getRoleAdmin(role) == expectedAdmin);
    }
}

