pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(address target, uint256 value, bytes calldata data, bytes32 salt, uint256 delay, bytes32 id) public {
        // Bound delay to be >= minDelay (which is 0)
        delay = bound(delay, 0, 1000000);

        // Compute operation id if not provided
        bytes32 opId = c.hashOperation(target, value, data, bytes32(0), salt);
        if (id != bytes32(0)) opId = id;

        // Schedule the operation (needs PROPOSER_ROLE)
        c.schedule(target, value, data, bytes32(0), salt, delay);

        // Cancel the operation (needs PROPOSER_ROLE)
        c.cancel(opId);

        // After cancel, the operation should not be pending
        bool pending = c.isOperationPending(opId);

        // The getter for getRoleAdmin should return TIMELOCK_ADMIN_ROLE for PROPOSER_ROLE
        bytes32 adminRole = c.getRoleAdmin(c.PROPOSER_ROLE());
        bytes32 expectedAdmin = c.TIMELOCK_ADMIN_ROLE();

        // In the reference, getRoleAdmin returns the admin role; in the bug it always returns 0x00
        assertTrue(!pending || adminRole == expectedAdmin, "After cancel, operation should not be pending or admin role must be correct");
    }
}

