// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(
        address target,
        uint256 value,
        bytes memory data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay,
        bytes32 cancelId
    ) public {
        // Bound delay to avoid overflow
        vm.assume(delay <= 1000000);
        // Bound cancelId to cover both scheduled and unscheduled cases

        // Call schedule to create an operation (if delay allows)
        try c.schedule(target, value, data, predecessor, salt, delay) {
            // Operation scheduled - get its id
            bytes32 scheduledId = c.hashOperation(target, value, data, predecessor, salt);
            // Remember timestamp before cancel
            uint256 beforeTimestamp = c.getTimestamp(scheduledId);

            // Try to cancel the scheduled operation
            bool cancelReverted;
            try c.cancel(scheduledId) {
                cancelReverted = false;
            } catch {
                cancelReverted = true;
            }

            // After cancel, the operation should either be canceled (timestamp 0) or untouched
            uint256 afterTimestamp = c.getTimestamp(scheduledId);

            // General rule: cancel should not set timestamp to DONE_TIMESTAMP (1) 
            // unless the operation was already ready (which in practice cannot happen because cancel requires pending)
            // The rule: after a cancel attempt, if the call didn't revert, timestamp must be 0;
            // if it reverted, timestamp must be unchanged.
            assertTrue(
                (cancelReverted && afterTimestamp == beforeTimestamp) ||
                (!cancelReverted && afterTimestamp == 0) ||
                (!cancelReverted && afterTimestamp == beforeTimestamp) // case where cancel did nothing (already not pending)
            );
        } catch {
            // If schedule fails, test passes trivially
            assertTrue(true);
        }
    }
}

