        vm.assume(delay >= c.getMinDelay());

        // Schedule an operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Record timestamp before cancel
        uint256 before = c.getTimestamp(id);

        // Cancel the operation
        c.cancel(id);

        // Record timestamp after cancel
        uint256 after = c.getTimestamp(id);

        // Assert: after cancel, timestamp is either 0 or unchanged, never DONE_TIMESTAMP (1)
        assertTrue(after == 0 || after == before);
    }
}

