// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address attacker, bytes32 role, address account) public {
        vm.assume(account != address(this));
        vm.assume(attacker != address(this));
        vm.assume(account != attacker);

        // Schedule an operation as proposer
        bytes32 salt = keccak256(abi.encode(attacker, role, account));
        address target = address(0);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        uint256 delay = 1;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Cancel it
        c.cancel(id);

        // Try to renounce a different role (not the caller's own role)
        // In reference, this reverts with require(account != _msgSender())
        // In mutant, this succeeds (since the condition is flipped)
        try this.doRenounceRole(c, role, account) {
            // If it doesn't revert, the mutant is detected
        } catch {
            revert("Reference reverts, but mutant should not");
        }

        // The rule: after cancel, renounceRole on another account should revert in reference
        // We check that the operation is no longer pending (was cancelled)
        assertTrue(!c.isOperationPending(id), "Operation should not be pending after cancel");
    }

    function doRenounceRole(C _c, bytes32 role, address account) external {
        _c.renounceRole(role, account);
    }
}

