    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        // Bound delay to be at least minDelay (0)
        delay = bound(delay, 0, 365 days);

        // Schedule an operation (we need a pending operation to cancel)
        // We are the PROPOSER_ROLE because we deployed the contract
        vm.assume(target != address(0));

        // Use a reasonable value (no ether needed)
        value = 0;

        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 opId = c.hashOperation(target, value, data, predecessor, salt);

        // Cancel the operation
        c.cancel(opId);

        // Now test renounceRole: we should be able to renounce our own role
        // The reference allows this; the mutant reverts.
        bool success;
        (success, ) = address(c).call(abi.encodeWithSignature("renounceRole(bytes32,address)", c.PROPOSER_ROLE(), address(this)));
        assertTrue(success, "renounceRole should succeed after cancel");
    }
}

