import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure the operation is considered done (i.e., timestamp == _DONE_TIMESTAMP == 1)
        // We simulate this by scheduling, then executing a dummy call to set the done state.
        // However, we cannot directly set the timestamp, so we use a different approach:
        // We'll attempt to cancel an operation that we know should revert if it's already done.
        // The only way to get a 'done' operation is through execute, but that requires roles.
        // Since the test is for the difference, we assume that cancel(0x0) will revert in P but succeed in M.
        // But we need a general rule. Let's use schedule + execute + then cancel on the executed id.
        // We'll use a dummy target (this contract) with empty call.
        // First, schedule a dummy operation with delay 0.
        address target = address(this);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = id;
        uint256 delay = 0;
        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 operationId = c.hashOperation(target, value, data, predecessor, salt);
        // Execute the operation (needs executor role, which this contract has)
        c.execute(target, value, data, predecessor, salt);
        // Now the operation should be done (timestamp == _DONE_TIMESTAMP == 1)
        // Attempt to cancel; in P, this should revert; in M, it might succeed.
        // We capture whether it reverts.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", operationId));
        // The rule: cancelling a done operation must revert.
        assertTrue(!ok, "cancel on done operation should revert");
    }
}

