import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt) public {
        // Bound value to avoid overflow issues
        value = bound(value, 0, 1e30);

        // Compute the id that would be scheduled
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Schedule the operation (caller has PROPOSER_ROLE)
        uint256 delay = 7 days;
        c.schedule(target, value, data, predecessor, salt, delay);

        // Record isOperationPending immediately after scheduling (still pending)
        bool pendingBefore = c.isOperationPending(id);

