        // But we need to check the property: after a successful cancel, isOperationPending must have been true before the call
        // For the reference, cancel will revert when isOperationPending is false
        // So we test: if cancel does NOT revert, then isOperationPending was true before the call
        bool cancelSucceeded;
        try c.cancel(id) {
            cancelSucceeded = true;
        } catch {
            cancelSucceeded = false;
        }

        // General rule: prior to a successful cancel, isOperationPending must have returned true at the time of the schedule
        assertTrue(!cancelSucceeded || pendingBefore);
    }
}

