        // Let's define the property: "if isOperationReady(id) returns false, then either the operation is not pending (getTimestamp(id) <= 1) or the operation's timestamp is greater than block.timestamp." This holds for M? Actually M returns false when timestamp == block.timestamp, so the condition getTimestamp(id) > block.timestamp would be false, and getTimestamp(id) > 1 is true, so the property fails for M when timestamp == block.timestamp.
        // So the rule: !isOperationReady(id) => (getTimestamp(id) <= 1 || getTimestamp(id) > block.timestamp)
        bool ready = c.isOperationReady(id);
        uint256 t = c.getTimestamp(id);
        assertTrue(!ready || (t > 1 && t <= block.timestamp)); // if ready, then timestamp is >1 and <= now
        // The above holds for both. We need a rule that P satisfies and M breaks.
        // Alternative: Use the fact that for any id, if getTimestamp(id) == block.timestamp, then isOperationReady(id) must be true. That holds for P but not M.
        if (t == block.timestamp) {
            assertTrue(ready);
        }
        // That's the property that catches the bug: when timestamp equals block.timestamp, P returns true, M returns false.
    }
