        // The buggy version returns false for readiness, so cancel will not revert
        bool reverted = false;
        try c.cancel(c.hashOperation(target, value, data, predecessor, salt)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: cancel MUST revert when the operation is ready
        // Ready means gotTimestamp > _DONE_TIMESTAMP && gotTimestamp <= block.timestamp
        // After warp, gotTimestamp == block.timestamp, so ready in P, not in M
        // In P, cancel reverts; in M, cancel succeeds
        // So our assertion: cancel should have reverted
        assertTrue(reverted, "cancel should revert when operation is ready");
    }
}

